CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE SCHEMA IF NOT EXISTS erp;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_app') THEN CREATE ROLE saman_app NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_migrator') THEN CREATE ROLE saman_migrator NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_worker') THEN CREATE ROLE saman_worker NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_readonly') THEN CREATE ROLE saman_readonly NOLOGIN; END IF;
END $$;
SET search_path TO erp, public;
COMMENT ON SCHEMA erp IS 'Saman ERP business schema (single schema; module.table notation is ownership only)';

-- ---------- shared trigger functions ----------
CREATE OR REPLACE FUNCTION erp.set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at := now(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION erp.bump_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.version := OLD.version + 1; RETURN NEW; END $$;

-- tenant root
CREATE TABLE IF NOT EXISTS erp."organizations" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "name" varchar(200) NOT NULL,
  "legal_name" varchar(300),
  "national_id" varchar(20),
  "economic_code" varchar(20),
  "registration_no" varchar(30),
  "base_currency" char(3) NOT NULL DEFAULT 'IRR',
  "timezone" varchar(64) NOT NULL DEFAULT 'Asia/Tehran',
  "fiscal_year_start_month" smallint NOT NULL DEFAULT 1,
  "fiscal_year_start_day" smallint NOT NULL DEFAULT 1,
  "valuation_method" varchar(20) NOT NULL DEFAULT 'moving_average',
  "allow_negative_stock" boolean NOT NULL DEFAULT false,
  "status" varchar(20) NOT NULL DEFAULT 'active',
  "logo_file_id" bigint,
  CONSTRAINT "pk_organizations" PRIMARY KEY ("id"),
  CONSTRAINT "uq_organizations_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_organizations_national_id" UNIQUE ("national_id"),
  CONSTRAINT "ck_organizations_fiscal_month" CHECK (fiscal_year_start_month between 1 and 12)
);
CREATE INDEX IF NOT EXISTS ix_organizations_name ON erp."organizations" ("name");
CREATE TRIGGER trg_organizations_updated_at BEFORE UPDATE ON erp."organizations" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_organizations_version BEFORE UPDATE ON erp."organizations" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

