-- global permission registry (412 keys from API.md §5.2)
CREATE TABLE IF NOT EXISTS erp."permissions" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "key" varchar(120) NOT NULL,
  "resource" varchar(80) NOT NULL,
  "action" varchar(40) NOT NULL,
  "description_fa" varchar(300) NOT NULL,
  "is_system" boolean NOT NULL DEFAULT true,
  "module" varchar(40) NOT NULL,
  CONSTRAINT "uq_permissions_key" UNIQUE ("key"),
  CONSTRAINT "pk_permissions" PRIMARY KEY ("id"),
  CONSTRAINT "uq_permissions_resource_action" UNIQUE ("resource","action"),
  CONSTRAINT "ck_permissions_key_format" CHECK (key ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$' and key = resource || '.' || action)
);
CREATE INDEX IF NOT EXISTS ix_permissions_module ON erp."permissions" ("module");

