  "device_id" bigint,
  "ip_address" inet,
  "ip_prefix" inet,
  "user_agent_hash" char(64),
  "mfa_verified" boolean NOT NULL DEFAULT false,
  "last_used_at" timestamptz,
  "expires_at" timestamptz NOT NULL,
  "absolute_expires_at" timestamptz NOT NULL,
  "revoked_at" timestamptz,
  "revoke_reason" varchar(40),
  CONSTRAINT "pk_auth_sessions" PRIMARY KEY ("id"),
  CONSTRAINT "uq_auth_sessions_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_auth_sessions_user_id" FOREIGN KEY ("user_id") REFERENCES erp."users" (id) ON DELETE CASCADE,
  CONSTRAINT "uq_auth_sessions_refresh_token_hash" UNIQUE ("refresh_token_hash")
);
CREATE INDEX IF NOT EXISTS ix_auth_sessions_user_id_revoked_at ON erp."auth_sessions" ("user_id","revoked_at");
CREATE INDEX IF NOT EXISTS ix_auth_sessions_session_family_id ON erp."auth_sessions" ("session_family_id");
CREATE INDEX IF NOT EXISTS ix_auth_sessions_expires_at ON erp."auth_sessions" ("expires_at");

-- trusted devices; server-issued secret is the only trust factor (R1-S B-02)
CREATE TABLE IF NOT EXISTS erp."user_devices" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "user_id" bigint NOT NULL,
  "device_fingerprint_hash" char(64) NOT NULL,
  "device_secret_hash" char(64) NOT NULL,
  "secret_issued_at" timestamptz NOT NULL DEFAULT now(),
  "secret_rotated_at" timestamptz,
  "label" varchar(150),
  "platform" varchar(40),
  "user_agent_hash" char(64),
  "trusted" boolean NOT NULL DEFAULT false,
  "trusted_until" timestamptz,
  "first_seen_at" timestamptz NOT NULL DEFAULT now(),
  "last_seen_at" timestamptz NOT NULL DEFAULT now(),
  "revoked_at" timestamptz,
  CONSTRAINT "pk_user_devices" PRIMARY KEY ("id"),
  CONSTRAINT "uq_user_devices_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_user_devices_user_id" FOREIGN KEY ("user_id") REFERENCES erp."users" (id) ON DELETE CASCADE,
  CONSTRAINT "uq_user_devices_user_id_device_fingerprint_hash" UNIQUE ("user_id","device_fingerprint_hash")
);
CREATE INDEX IF NOT EXISTS ix_user_devices_user_id_trusted ON erp."user_devices" ("user_id","trusted");
CREATE TRIGGER trg_user_devices_updated_at BEFORE UPDATE ON erp."user_devices" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_user_devices_version BEFORE UPDATE ON erp."user_devices" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

