CREATE SEQUENCE IF NOT EXISTS erp.audit_logs_id_seq AS bigint START 1 INCREMENT 1;
-- append-only audit (hash-chained; partitioned monthly)
CREATE TABLE IF NOT EXISTS erp."audit_logs" (
  "id" bigint NOT NULL DEFAULT nextval('erp.audit_logs_id_seq'),
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "organization_id" bigint NOT NULL,
  "actor_user_id" bigint,
  "actor_type" varchar(20) NOT NULL DEFAULT 'user',
  "actor_label" varchar(150),
  "api_client_id" bigint,
  "entity_type" varchar(100) NOT NULL,
  "entity_id" bigint,
  "entity_public_id" uuid,
  "action" varchar(80) NOT NULL,
  "old_data" jsonb,
  "new_data" jsonb,
  "diff" jsonb,
  "prev_hash" char(64),
  "entry_hash" char(64),
  "hash_seq" bigint,
  "ip_address" inet,
  "user_agent_hash" char(64),
  "request_id" uuid,
  "trace_id" varchar(64),
  "severity" varchar(10) NOT NULL DEFAULT 'info',
  CONSTRAINT "pk_audit_logs" PRIMARY KEY ("id","created_at"),
  CONSTRAINT "uq_audit_logs_public_id_created_at" UNIQUE ("public_id","created_at")
) PARTITION BY RANGE ("created_at");
CREATE TABLE IF NOT EXISTS erp.audit_logs_default PARTITION OF erp.audit_logs DEFAULT;
CREATE INDEX IF NOT EXISTS ix_audit_logs_created_at_brin ON erp.audit_logs USING brin ("created_at") WITH (pages_per_range = 32);
CREATE TABLE IF NOT EXISTS erp.audit_logs_p202610 PARTITION OF erp.audit_logs FOR VALUES FROM ('2026-10-01 00:00:00+00') TO ('2026-11-01 00:00:00+00');
CREATE TABLE IF NOT EXISTS erp.audit_logs_p202611 PARTITION OF erp.audit_logs FOR VALUES FROM ('2026-11-01 00:00:00+00') TO ('2026-12-01 00:00:00+00');
CREATE INDEX IF NOT EXISTS ix_audit_logs_organization_id_created_at ON erp."audit_logs" ("organization_id","created_at");
CREATE INDEX IF NOT EXISTS ix_audit_logs_entity_type_entity_id_created_at ON erp."audit_logs" ("entity_type","entity_id","created_at");
CREATE INDEX IF NOT EXISTS ix_audit_logs_actor_user_id_created_at ON erp."audit_logs" ("actor_user_id","created_at");
CREATE INDEX IF NOT EXISTS ix_audit_logs_action_created_at ON erp."audit_logs" ("action","created_at");

-- org-scoped settings; secrets encrypted
CREATE TABLE IF NOT EXISTS erp."system_settings" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
