  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "key" varchar(150) NOT NULL,
  "value_json" jsonb NOT NULL DEFAULT '{}',
  "is_secret" boolean NOT NULL DEFAULT false,
  "description_fa" varchar(300),
  CONSTRAINT "pk_system_settings" PRIMARY KEY ("id"),
  CONSTRAINT "uq_system_settings_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_system_settings_organization_id" FOREIGN KEY ("organization_id") REFERENCES erp."organizations" (id) ON DELETE RESTRICT,
  CONSTRAINT "uq_system_settings_organization_id_key" UNIQUE ("organization_id","key")
);
CREATE INDEX IF NOT EXISTS ix_system_settings_organization_id ON erp."system_settings" ("organization_id");
CREATE TRIGGER trg_system_settings_updated_at BEFORE UPDATE ON erp."system_settings" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_system_settings_version BEFORE UPDATE ON erp."system_settings" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

