  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "file_name" varchar(255) NOT NULL,
  "mime_type" varchar(120) NOT NULL,
  "storage_provider" varchar(20) NOT NULL DEFAULT 's3',
  "bucket" varchar(120) NOT NULL,
  "storage_key" text NOT NULL,
  "size_bytes" bigint NOT NULL DEFAULT 0,
  "sha256" char(64) NOT NULL,
  "media_kind" varchar(20) NOT NULL DEFAULT 'document',
  "visibility" varchar(10) NOT NULL DEFAULT 'private',
  "scan_state" varchar(20) NOT NULL DEFAULT 'pending',
  "quarantine_path" text,
  "uploaded_by" bigint,
  "ready_at" timestamptz,
  "owner_entity_type" varchar(60),
  "owner_entity_id" bigint,
  "metadata" jsonb NOT NULL DEFAULT '{}',
  CONSTRAINT "pk_file_assets" PRIMARY KEY ("id"),
  CONSTRAINT "uq_file_assets_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_file_assets_bucket_storage_key" UNIQUE ("bucket","storage_key")
);
CREATE INDEX IF NOT EXISTS ix_file_assets_owner_entity_type_owner_entity_id ON erp."file_assets" ("owner_entity_type","owner_entity_id");
CREATE INDEX IF NOT EXISTS ix_file_assets_organization_id ON erp."file_assets" ("organization_id");
CREATE TRIGGER trg_file_assets_updated_at BEFORE UPDATE ON erp."file_assets" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_file_assets_version BEFORE UPDATE ON erp."file_assets" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- polymorphic file↔entity links (R1-D B-01)
