CREATE TRIGGER trg_file_links_updated_at BEFORE UPDATE ON erp."file_links" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_file_links_version BEFORE UPDATE ON erp."file_links" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

