CREATE TRIGGER trg_notifications_version BEFORE UPDATE ON erp."notifications" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- HTTP idempotency replay store (actor-scoped)
CREATE TABLE IF NOT EXISTS erp."idempotency_keys" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "actor_user_id" bigint,
  "key" varchar(200) NOT NULL,
  "scope" varchar(120) NOT NULL,
  "request_hash" char(64) NOT NULL,
  "response_code" smallint,
  "response_body" jsonb,
  "resource_type" varchar(60),
  "resource_public_id" uuid,
  "expires_at" timestamptz NOT NULL,
  CONSTRAINT "pk_idempotency_keys" PRIMARY KEY ("id"),
  CONSTRAINT "uq_idempotency_keys_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_idempotency_keys_organization_id_actor_user_id_scope_key" UNIQUE ("organization_id","actor_user_id","scope","key")
);
CREATE INDEX IF NOT EXISTS ix_idempotency_keys_expires_at ON erp."idempotency_keys" ("expires_at");
CREATE TRIGGER trg_idempotency_keys_updated_at BEFORE UPDATE ON erp."idempotency_keys" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_idempotency_keys_version BEFORE UPDATE ON erp."idempotency_keys" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

CREATE SEQUENCE IF NOT EXISTS erp.outbox_events_id_seq AS bigint START 1 INCREMENT 1;
-- transactional outbox (partitioned monthly)
CREATE TABLE IF NOT EXISTS erp."outbox_events" (
  "id" bigint NOT NULL DEFAULT nextval('erp.outbox_events_id_seq'),
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "version" integer NOT NULL DEFAULT 1,
  "created_by" bigint,
  "organization_id" bigint NOT NULL,
  "event_type" varchar(100) NOT NULL,
  "event_version" smallint NOT NULL DEFAULT 1,
  "aggregate_type" varchar(80) NOT NULL,
  "aggregate_id" bigint NOT NULL,
  "aggregate_public_id" uuid,
  "payload" jsonb NOT NULL,
  "headers" jsonb NOT NULL DEFAULT '{}',
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "available_at" timestamptz NOT NULL DEFAULT now(),
  "attempts" smallint NOT NULL DEFAULT 0,
  "max_attempts" smallint NOT NULL DEFAULT 10,
  "locked_by" varchar(80),
  "locked_at" timestamptz,
  "locked_until" timestamptz,
  "event_uuid" uuid NOT NULL DEFAULT gen_random_uuid(),
  "processed_at" timestamptz,
  "last_error" text,
  "trace_id" varchar(64),
  CONSTRAINT "pk_outbox_events" PRIMARY KEY ("id","created_at"),
  CONSTRAINT "uq_outbox_events_public_id_created_at" UNIQUE ("public_id","created_at"),
  CONSTRAINT "uq_outbox_events_event_uuid_created_at" UNIQUE ("event_uuid","created_at"),
  CONSTRAINT "ck_outbox_events_status" CHECK (status in ('pending','processing','processed','failed')),
  CONSTRAINT "ck_outbox_events_attempts" CHECK (attempts >= 0 and attempts <= max_attempts)
) PARTITION BY RANGE ("created_at");
CREATE TABLE IF NOT EXISTS erp.outbox_events_default PARTITION OF erp.outbox_events DEFAULT;
CREATE INDEX IF NOT EXISTS ix_outbox_events_created_at_brin ON erp.outbox_events USING brin ("created_at") WITH (pages_per_range = 32);
CREATE TABLE IF NOT EXISTS erp.outbox_events_p202610 PARTITION OF erp.outbox_events FOR VALUES FROM ('2026-10-01 00:00:00+00') TO ('2026-11-01 00:00:00+00');
CREATE TABLE IF NOT EXISTS erp.outbox_events_p202611 PARTITION OF erp.outbox_events FOR VALUES FROM ('2026-11-01 00:00:00+00') TO ('2026-12-01 00:00:00+00');
CREATE TRIGGER trg_outbox_events_updated_at BEFORE UPDATE ON erp."outbox_events" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_outbox_events_version BEFORE UPDATE ON erp."outbox_events" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- non-partitioned global outbox dedupe
CREATE TABLE IF NOT EXISTS erp."outbox_event_keys" (
  "event_type" varchar(100) NOT NULL,
  "aggregate_type" varchar(80) NOT NULL,
  "aggregate_id" bigint NOT NULL,
  "event_version" smallint NOT NULL,
  "event_uuid" uuid,
  "organization_id" bigint NOT NULL,
  "outbox_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_outbox_event_keys" PRIMARY KEY ("event_uuid"),
  CONSTRAINT "uq_outbox_event_keys_event_type_aggregate_type_aggregate_id_event_version" UNIQUE ("event_type","aggregate_type","aggregate_id","event_version")
);
CREATE INDEX IF NOT EXISTS ix_outbox_event_keys_created_at ON erp."outbox_event_keys" ("created_at");

