  "http_status" smallint,
  "response_snippet" varchar(500),
  "duration_ms" integer,
  "next_retry_at" timestamptz,
  "delivered_at" timestamptz,
  "error_message" text,
  "request_payload" jsonb,
  CONSTRAINT "pk_webhook_deliveries" PRIMARY KEY ("id"),
  CONSTRAINT "uq_webhook_deliveries_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_webhook_deliveries_subscription_id" FOREIGN KEY ("subscription_id") REFERENCES erp."webhook_subscriptions" (id) ON DELETE CASCADE,
  CONSTRAINT "uq_webhook_deliveries_subscription_id_event_uuid_attempt_no" UNIQUE ("subscription_id","event_uuid","attempt_no")
);
CREATE INDEX IF NOT EXISTS ix_webhook_deliveries_status_next_retry_at ON erp."webhook_deliveries" ("status","next_retry_at");
CREATE INDEX IF NOT EXISTS ix_webhook_deliveries_event_uuid ON erp."webhook_deliveries" ("event_uuid");

-- durable background-job record (GET /jobs/{id})
CREATE TABLE IF NOT EXISTS erp."job_runs" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "job_key" uuid NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" bigint,
  "queue" varchar(40) NOT NULL,
  "job_type" varchar(80) NOT NULL,
  "entity_type" varchar(60),
  "entity_id" bigint,
  "status" varchar(20) NOT NULL DEFAULT 'queued',
  "priority" integer NOT NULL DEFAULT 0,
  "attempts" smallint NOT NULL DEFAULT 0,
  "max_attempts" smallint NOT NULL DEFAULT 10,
  "scheduled_at" timestamptz,
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "duration_ms" integer,
  "payload" jsonb NOT NULL DEFAULT '{}',
  "result" jsonb,
  "error_code" varchar(60),
  "error_message" text,
  "worker_id" varchar(80),
  "bullmq_job_id" varchar(80),
  "requested_by" bigint,
  "progress_percent" smallint NOT NULL DEFAULT 0,
  CONSTRAINT "pk_job_runs" PRIMARY KEY ("id"),
  CONSTRAINT "uq_job_runs_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_job_runs_job_key" UNIQUE ("job_key")
);
CREATE INDEX IF NOT EXISTS ix_job_runs_status_scheduled_at ON erp."job_runs" ("status","scheduled_at");
CREATE INDEX IF NOT EXISTS ix_job_runs_queue_job_type_created_at ON erp."job_runs" ("queue","job_type","created_at");
CREATE INDEX IF NOT EXISTS ix_job_runs_entity_type_entity_id ON erp."job_runs" ("entity_type","entity_id");
CREATE TRIGGER trg_job_runs_updated_at BEFORE UPDATE ON erp."job_runs" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_job_runs_version BEFORE UPDATE ON erp."job_runs" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- job step status
CREATE TABLE IF NOT EXISTS erp."job_steps" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "job_run_id" bigint NOT NULL,
  "step_no" integer NOT NULL,
  "name" varchar(120) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'queued',
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "detail" jsonb,
  "error_message" text,
  CONSTRAINT "pk_job_steps" PRIMARY KEY ("id"),
  CONSTRAINT "uq_job_steps_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_job_steps_job_run_id" FOREIGN KEY ("job_run_id") REFERENCES erp."job_runs" (id) ON DELETE CASCADE,
  CONSTRAINT "uq_job_steps_job_run_id_step_no" UNIQUE ("job_run_id","step_no")
);

-- machine clients (scopes/cidrs/hashed secrets)
CREATE TABLE IF NOT EXISTS erp."api_clients" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "deleted_at" timestamptz,
  "organization_id" bigint NOT NULL,
  "name" varchar(150) NOT NULL,
  "client_key" varchar(60) NOT NULL,
  "secret_hash" varchar(255) NOT NULL,
  "previous_secret_hash" varchar(255),
  "scopes" jsonb NOT NULL DEFAULT '[]',
  "allowed_cidrs" cidr[],
  "rate_limit_per_min" integer NOT NULL DEFAULT 120,
  "is_active" boolean NOT NULL DEFAULT true,
  "last_used_at" timestamptz,
  "expires_at" timestamptz,
  "rotated_at" timestamptz,
  CONSTRAINT "pk_api_clients" PRIMARY KEY ("id"),
  CONSTRAINT "uq_api_clients_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_api_clients_client_key" UNIQUE ("client_key")
);
CREATE INDEX IF NOT EXISTS ix_api_clients_organization_id ON erp."api_clients" ("organization_id");
CREATE TRIGGER trg_api_clients_updated_at BEFORE UPDATE ON erp."api_clients" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_api_clients_version BEFORE UPDATE ON erp."api_clients" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

CREATE SEQUENCE IF NOT EXISTS erp.api_request_logs_id_seq AS bigint START 1 INCREMENT 1;
-- HTTP access log (partitioned; 90 days)
CREATE TABLE IF NOT EXISTS erp."api_request_logs" (
  "id" bigint NOT NULL DEFAULT nextval('erp.api_request_logs_id_seq'),
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "organization_id" bigint,
  "api_client_id" bigint,
  "user_id" bigint,
  "method" varchar(10) NOT NULL,
  "path" text NOT NULL,
  "route_pattern" varchar(200),
  "query_string" text,
  "request_id" uuid NOT NULL,
  "status_code" smallint NOT NULL,
  "error_code" varchar(40),
  "request_bytes" integer,
  "response_bytes" integer,
  "latency_ms" integer,
  "db_time_ms" integer,
  "ip_address" inet,
  "user_agent_hash" char(64),
  "rate_limited" boolean NOT NULL DEFAULT false,
  CONSTRAINT "pk_api_request_logs" PRIMARY KEY ("id","created_at"),
  CONSTRAINT "uq_api_request_logs_public_id_created_at" UNIQUE ("public_id","created_at")
) PARTITION BY RANGE ("created_at");
CREATE TABLE IF NOT EXISTS erp.api_request_logs_default PARTITION OF erp.api_request_logs DEFAULT;
CREATE INDEX IF NOT EXISTS ix_api_request_logs_created_at_brin ON erp.api_request_logs USING brin ("created_at") WITH (pages_per_range = 32);
CREATE TABLE IF NOT EXISTS erp.api_request_logs_p202610 PARTITION OF erp.api_request_logs FOR VALUES FROM ('2026-10-01 00:00:00+00') TO ('2026-11-01 00:00:00+00');
CREATE TABLE IF NOT EXISTS erp.api_request_logs_p202611 PARTITION OF erp.api_request_logs FOR VALUES FROM ('2026-11-01 00:00:00+00') TO ('2026-12-01 00:00:00+00');
CREATE INDEX IF NOT EXISTS ix_api_request_logs_organization_id_created_at ON erp."api_request_logs" ("organization_id","created_at");
CREATE INDEX IF NOT EXISTS ix_api_request_logs_status_code_created_at ON erp."api_request_logs" ("status_code","created_at");
CREATE INDEX IF NOT EXISTS ix_api_request_logs_request_id ON erp."api_request_logs" ("request_id");

-- immutable entity version snapshots
CREATE TABLE IF NOT EXISTS erp."data_versions" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "organization_id" bigint NOT NULL,
  "entity_type" varchar(100) NOT NULL,
  "entity_id" bigint NOT NULL,
  "version_no" integer NOT NULL,
  "data" jsonb NOT NULL,
  "changed_by" bigint,
  "changed_at" timestamptz NOT NULL DEFAULT now(),
  "change_reason" varchar(300),
  CONSTRAINT "pk_data_versions" PRIMARY KEY ("id"),
  CONSTRAINT "uq_data_versions_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_data_versions_entity_type_entity_id_version_no" UNIQUE ("entity_type","entity_id","version_no")
);
CREATE INDEX IF NOT EXISTS ix_data_versions_entity_type_entity_id_changed_at ON erp."data_versions" ("entity_type","entity_id","changed_at");

-- user saved filters/views
CREATE TABLE IF NOT EXISTS erp."saved_filters" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
