CREATE TRIGGER trg_saved_filters_updated_at BEFORE UPDATE ON erp."saved_filters" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_saved_filters_version BEFORE UPDATE ON erp."saved_filters" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

