CREATE TABLE IF NOT EXISTS erp."import_errors" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
