  CONSTRAINT "uq_import_errors_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_import_errors_import_job_id" FOREIGN KEY ("import_job_id") REFERENCES erp."import_jobs" (id) ON DELETE CASCADE
);
