CREATE TRIGGER trg_sms_templates_updated_at BEFORE UPDATE ON erp."sms_templates" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_sms_templates_version BEFORE UPDATE ON erp."sms_templates" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

