  CONSTRAINT "uq_fx_rates_organization_id_currency_code_effective_date" UNIQUE ("organization_id","currency_code","effective_date")
);
CREATE INDEX IF NOT EXISTS ix_fx_rates_currency_code_effective_date ON erp."fx_rates" ("currency_code","effective_date");
CREATE TRIGGER trg_fx_rates_updated_at BEFORE UPDATE ON erp."fx_rates" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_fx_rates_version BEFORE UPDATE ON erp."fx_rates" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- business calendar
CREATE TABLE IF NOT EXISTS erp."holidays" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
