CREATE TRIGGER trg_holidays_updated_at BEFORE UPDATE ON erp."holidays" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_holidays_version BEFORE UPDATE ON erp."holidays" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- fiscal year (Jalali) + closing state
CREATE TABLE IF NOT EXISTS erp."fiscal_years" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "code" varchar(20) NOT NULL,
  "title" varchar(100) NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'open',
  "closed_at" timestamptz,
  "closed_by" bigint,
  "closing_run_id" bigint,
  "opening_entry_id" bigint,
  CONSTRAINT "pk_fiscal_years" PRIMARY KEY ("id"),
  CONSTRAINT "uq_fiscal_years_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_fiscal_years_organization_id" FOREIGN KEY ("organization_id") REFERENCES erp."organizations" (id) ON DELETE RESTRICT,
  CONSTRAINT "uq_fiscal_years_organization_id_code" UNIQUE ("organization_id","code"),
  CONSTRAINT "uq_fiscal_years_organization_id_start_date_end_date" UNIQUE ("organization_id","start_date","end_date"),
  CONSTRAINT "ck_fiscal_years_range" CHECK (end_date > start_date),
  CONSTRAINT "ck_fiscal_years_status" CHECK (status in ('open','closing','closed'))
);
CREATE TRIGGER trg_fiscal_years_updated_at BEFORE UPDATE ON erp."fiscal_years" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_fiscal_years_version BEFORE UPDATE ON erp."fiscal_years" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- monthly periods; period 13 = adjustment
CREATE TABLE IF NOT EXISTS erp."accounting_periods" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "fiscal_year_id" bigint NOT NULL,
  "period_no" smallint NOT NULL,
  "name_fa" varchar(100) NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'open',
  "closed_at" timestamptz,
  "closed_by" bigint,
  CONSTRAINT "pk_accounting_periods" PRIMARY KEY ("id"),
  CONSTRAINT "uq_accounting_periods_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_accounting_periods_fiscal_year_id" FOREIGN KEY ("fiscal_year_id") REFERENCES erp."fiscal_years" (id) ON DELETE CASCADE,
