  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "deleted_at" timestamptz,
  "product_variant_id" bigint NOT NULL,
  "supplier_id" bigint NOT NULL,
  "supplier_sku" varchar(100),
  "purchase_price_amount" bigint NOT NULL DEFAULT 0,
  "currency" char(3) NOT NULL DEFAULT 'IRR',
  "lead_time_days" integer NOT NULL DEFAULT 0,
  "min_order_qty" numeric(18,4),
  "is_primary" boolean NOT NULL DEFAULT false,
  "last_purchase_at" timestamptz,
  CONSTRAINT "pk_product_suppliers" PRIMARY KEY ("id"),
  CONSTRAINT "uq_product_suppliers_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_product_suppliers_product_variant_id" FOREIGN KEY ("product_variant_id") REFERENCES erp."product_variants" (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_product_suppliers_supplier_id ON erp."product_suppliers" ("supplier_id");
CREATE UNIQUE INDEX IF NOT EXISTS uq_product_suppliers_product_variant_id_supplier_id_active ON erp."product_suppliers" ("product_variant_id","supplier_id") WHERE deleted_at IS NULL;
CREATE TRIGGER trg_product_suppliers_updated_at BEFORE UPDATE ON erp."product_suppliers" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_product_suppliers_version BEFORE UPDATE ON erp."product_suppliers" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

