CREATE INDEX IF NOT EXISTS ix_pick_tasks_wave_id ON erp."pick_tasks" ("wave_id");
CREATE INDEX IF NOT EXISTS ix_pick_tasks_order_id ON erp."pick_tasks" ("order_id");
CREATE INDEX IF NOT EXISTS ix_pick_tasks_product_variant_id ON erp."pick_tasks" ("product_variant_id");
CREATE INDEX IF NOT EXISTS ix_pick_tasks_location_id ON erp."pick_tasks" ("location_id");
CREATE INDEX IF NOT EXISTS ix_pick_tasks_assigned_to ON erp."pick_tasks" ("assigned_to");
CREATE TRIGGER trg_pick_tasks_updated_at BEFORE UPDATE ON erp."pick_tasks" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_pick_tasks_version BEFORE UPDATE ON erp."pick_tasks" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- two-stage pick verification
CREATE TABLE IF NOT EXISTS erp."pick_scans" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "pick_task_id" bigint NOT NULL,
  "barcode" varchar(100) NOT NULL,
  "expected_barcode" varchar(100),
  "product_variant_id" bigint,
  "quantity" numeric(18,4) NOT NULL,
  "result" varchar(20) NOT NULL DEFAULT 'accepted',
  "scanned_by" bigint NOT NULL,
  "scan_source" varchar(20) NOT NULL DEFAULT 'scanner',
  "client_scan_id" uuid,
  "scanned_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_pick_scans" PRIMARY KEY ("id"),
  CONSTRAINT "uq_pick_scans_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_pick_scans_pick_task_id" FOREIGN KEY ("pick_task_id") REFERENCES erp."pick_tasks" (id) ON DELETE CASCADE,
  CONSTRAINT "uq_pick_scans_client_scan_id" UNIQUE ("client_scan_id")
);
CREATE INDEX IF NOT EXISTS ix_pick_scans_pick_task_id ON erp."pick_scans" ("pick_task_id");
CREATE INDEX IF NOT EXISTS ix_pick_scans_scanned_by ON erp."pick_scans" ("scanned_by");

-- partial unique (soft delete): warehouse_id,code
-- packing bench
CREATE TABLE IF NOT EXISTS erp."packing_stations" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
