CREATE TRIGGER trg_packing_stations_updated_at BEFORE UPDATE ON erp."packing_stations" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_packing_stations_version BEFORE UPDATE ON erp."packing_stations" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- pack order
CREATE TABLE IF NOT EXISTS erp."packing_tasks" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "order_id" bigint NOT NULL,
  "station_id" bigint,
  "shipment_id" bigint,
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "packer_id" bigint,
  "started_at" timestamptz,
  "completed_at" timestamptz,
  CONSTRAINT "pk_packing_tasks" PRIMARY KEY ("id"),
  CONSTRAINT "uq_packing_tasks_public_id" UNIQUE ("public_id")
);
CREATE INDEX IF NOT EXISTS ix_packing_tasks_status ON erp."packing_tasks" ("status");
CREATE INDEX IF NOT EXISTS ix_packing_tasks_order_id ON erp."packing_tasks" ("order_id");
CREATE INDEX IF NOT EXISTS ix_packing_tasks_station_id ON erp."packing_tasks" ("station_id");
CREATE TRIGGER trg_packing_tasks_updated_at BEFORE UPDATE ON erp."packing_tasks" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_packing_tasks_version BEFORE UPDATE ON erp."packing_tasks" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- pack verification
CREATE TABLE IF NOT EXISTS erp."packing_scans" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "packing_task_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "barcode" varchar(100) NOT NULL,
  "quantity" numeric(18,4) NOT NULL,
  "result" varchar(20) NOT NULL DEFAULT 'accepted',
  "scanned_by" bigint NOT NULL,
  "client_scan_id" uuid,
  "scanned_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_packing_scans" PRIMARY KEY ("id"),
  CONSTRAINT "uq_packing_scans_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_packing_scans_packing_task_id" FOREIGN KEY ("packing_task_id") REFERENCES erp."packing_tasks" (id) ON DELETE CASCADE,
  CONSTRAINT "uq_packing_scans_client_scan_id" UNIQUE ("client_scan_id")
);
CREATE INDEX IF NOT EXISTS ix_packing_scans_packing_task_id ON erp."packing_scans" ("packing_task_id");
CREATE INDEX IF NOT EXISTS ix_packing_scans_product_variant_id ON erp."packing_scans" ("product_variant_id");

-- hot stock projection; CHECK makes negative availability impossible
CREATE TABLE IF NOT EXISTS erp."inventory_balances" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "warehouse_id" bigint NOT NULL,
  "location_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "on_hand" numeric(18,4) NOT NULL DEFAULT 0,
  "reserved" numeric(18,4) NOT NULL DEFAULT 0,
  "safety_buffer" numeric(18,4) NOT NULL DEFAULT 0,
  "damaged" numeric(18,4) NOT NULL DEFAULT 0,
  "in_transit" numeric(18,4) NOT NULL DEFAULT 0,
  "last_transaction_id" bigint,
  "last_counted_at" timestamptz,
  CONSTRAINT "pk_inventory_balances" PRIMARY KEY ("id"),
  CONSTRAINT "uq_inventory_balances_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_inventory_balances_warehouse_id_location_id_product_variant_id" UNIQUE ("warehouse_id","location_id","product_variant_id"),
  CONSTRAINT "ck_inventory_balances_nonnegative" CHECK (on_hand >= 0 and reserved >= 0 and safety_buffer >= 0 and damaged >= 0 and in_transit >= 0),
  CONSTRAINT "ck_inventory_balances_available" CHECK (reserved + safety_buffer + damaged <= on_hand),
  CONSTRAINT "ck_inventory_balances_damaged_le" CHECK (damaged <= on_hand)
);
CREATE INDEX IF NOT EXISTS ix_inventory_balances_warehouse_id_product_variant_id ON erp."inventory_balances" ("warehouse_id","product_variant_id");
CREATE INDEX IF NOT EXISTS ix_inventory_balances_product_variant_id ON erp."inventory_balances" ("product_variant_id");
CREATE INDEX IF NOT EXISTS ix_inventory_balances_location_id ON erp."inventory_balances" ("location_id");
CREATE TRIGGER trg_inventory_balances_updated_at BEFORE UPDATE ON erp."inventory_balances" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_inventory_balances_version BEFORE UPDATE ON erp."inventory_balances" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- physical batch metadata only (cost in layers)
CREATE TABLE IF NOT EXISTS erp."inventory_lots" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "warehouse_id" bigint NOT NULL,
  "lot_no" varchar(100) NOT NULL,
  "batch_barcode" varchar(120),
  "manufacture_date" date,
  "expiry_date" date,
  "supplier_id" bigint,
  "goods_receipt_line_id" bigint,
  "status" varchar(20) NOT NULL DEFAULT 'available',
  "expiry_alert_at" timestamptz,
  CONSTRAINT "pk_inventory_lots" PRIMARY KEY ("id"),
  CONSTRAINT "uq_inventory_lots_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_inventory_lots_goods_receipt_line_id_lot_no" UNIQUE ("goods_receipt_line_id","lot_no")
);
CREATE INDEX IF NOT EXISTS ix_inventory_lots_product_variant_id ON erp."inventory_lots" ("product_variant_id");
CREATE INDEX IF NOT EXISTS ix_inventory_lots_warehouse_id_expiry_date ON erp."inventory_lots" ("warehouse_id","expiry_date");
CREATE INDEX IF NOT EXISTS ix_inventory_lots_supplier_id ON erp."inventory_lots" ("supplier_id");
CREATE TRIGGER trg_inventory_lots_updated_at BEFORE UPDATE ON erp."inventory_lots" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_inventory_lots_version BEFORE UPDATE ON erp."inventory_lots" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- append-only FIFO cost layers
CREATE TABLE IF NOT EXISTS erp."inventory_cost_layers" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "organization_id" bigint NOT NULL,
  "warehouse_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "lot_id" bigint,
  "goods_receipt_line_id" bigint,
  "receipt_transaction_id" bigint NOT NULL,
  "receipt_transaction_created_at" timestamptz NOT NULL,
  "source_kind" varchar(20) NOT NULL,
  "received_at" timestamptz NOT NULL,
  "original_qty" numeric(18,4) NOT NULL,
  "qty_remaining" numeric(18,4) NOT NULL,
  "unit_cost_amount" bigint NOT NULL,
  "cost_remaining_amount" bigint NOT NULL,
  "currency" char(3) NOT NULL DEFAULT 'IRR',
  "reversal_of_layer_id" bigint,
  "is_closed" boolean NOT NULL DEFAULT false,
  CONSTRAINT "pk_inventory_cost_layers" PRIMARY KEY ("id"),
  CONSTRAINT "uq_inventory_cost_layers_public_id" UNIQUE ("public_id"),
  CONSTRAINT "ck_inventory_cost_layers_qty" CHECK (qty_remaining >= 0 and qty_remaining <= original_qty),
  CONSTRAINT "ck_inventory_cost_layers_value" CHECK (cost_remaining_amount >= 0 and cost_remaining_amount <= unit_cost_amount * original_qty),
  CONSTRAINT "ck_inventory_cost_layers_closed" CHECK (not is_closed or qty_remaining = 0)
);
CREATE INDEX IF NOT EXISTS ix_inventory_cost_layers_warehouse_id_product_variant_id_received_at ON erp."inventory_cost_layers" ("warehouse_id","product_variant_id","received_at");
CREATE INDEX IF NOT EXISTS ix_inventory_cost_layers_receipt_transaction_id ON erp."inventory_cost_layers" ("receipt_transaction_id");
CREATE INDEX IF NOT EXISTS ix_inventory_cost_layers_lot_id ON erp."inventory_cost_layers" ("lot_id");

-- issue↔layer attribution
CREATE TABLE IF NOT EXISTS erp."inventory_layer_consumptions" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "layer_id" bigint NOT NULL,
  "issue_transaction_id" bigint NOT NULL,
  "issue_transaction_created_at" timestamptz NOT NULL,
  "warehouse_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "quantity" numeric(18,4) NOT NULL,
  "cost_amount" bigint NOT NULL,
  "consumption_kind" varchar(20) NOT NULL,
  "created_by" bigint,
  CONSTRAINT "pk_inventory_layer_consumptions" PRIMARY KEY ("id"),
  CONSTRAINT "uq_inventory_layer_consumptions_public_id" UNIQUE ("public_id")
);
CREATE INDEX IF NOT EXISTS ix_inventory_layer_consumptions_layer_id ON erp."inventory_layer_consumptions" ("layer_id");
CREATE INDEX IF NOT EXISTS ix_inventory_layer_consumptions_issue_transaction_id ON erp."inventory_layer_consumptions" ("issue_transaction_id");
CREATE INDEX IF NOT EXISTS ix_inventory_layer_consumptions_warehouse_id_product_variant_id ON erp."inventory_layer_consumptions" ("warehouse_id","product_variant_id");

-- moving-average state per warehouse×variant
CREATE TABLE IF NOT EXISTS erp."inventory_average_costs" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "warehouse_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "qty_on_hand" numeric(18,4) NOT NULL DEFAULT 0,
  "avg_cost_amount" bigint NOT NULL DEFAULT 0,
  "total_value_amount" bigint NOT NULL DEFAULT 0,
  "last_transaction_id" bigint,
  "last_calculated_at" timestamptz,
  CONSTRAINT "pk_inventory_average_costs" PRIMARY KEY ("id"),
  CONSTRAINT "uq_inventory_average_costs_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_inventory_average_costs_warehouse_id_product_variant_id" UNIQUE ("warehouse_id","product_variant_id"),
  CONSTRAINT "ck_inventory_average_costs_nonnegative" CHECK (qty_on_hand >= 0 and avg_cost_amount >= 0 and total_value_amount >= 0)
);
CREATE INDEX IF NOT EXISTS ix_inventory_average_costs_product_variant_id ON erp."inventory_average_costs" ("product_variant_id");
CREATE TRIGGER trg_inventory_average_costs_updated_at BEFORE UPDATE ON erp."inventory_average_costs" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_inventory_average_costs_version BEFORE UPDATE ON erp."inventory_average_costs" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- non-partitioned global ledger dedupe
CREATE TABLE IF NOT EXISTS erp."inventory_ledger_keys" (
  "idempotency_key" varchar(150),
  "organization_id" bigint NOT NULL,
  "inventory_transaction_id" bigint NOT NULL,
