CREATE SEQUENCE IF NOT EXISTS erp.inventory_transactions_id_seq AS bigint START 1 INCREMENT 1;
-- append-only movement ledger (partitioned)
CREATE TABLE IF NOT EXISTS erp."inventory_transactions" (
  "id" bigint NOT NULL DEFAULT nextval('erp.inventory_transactions_id_seq'),
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "organization_id" bigint NOT NULL,
  "warehouse_id" bigint NOT NULL,
  "location_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "transaction_type" varchar(30) NOT NULL,
  "quantity" numeric(18,4) NOT NULL,
  "unit_cost_amount" bigint,
  "total_cost_amount" bigint,
  "currency" char(3) NOT NULL DEFAULT 'IRR',
  "lot_id" bigint,
  "serial_id" bigint,
  "inventory_unit_id" bigint,
  "reference_type" varchar(50) NOT NULL,
  "reference_id" bigint,
  "reference_public_id" uuid,
  "reversal_of_id" bigint,
  "idempotency_key" varchar(120),
  "voided_at" timestamptz,
  "voided_by" bigint,
  "void_reason" varchar(300),
  "business_date" date NOT NULL DEFAULT current_date,
  "period_id" bigint NOT NULL,
  "journal_entry_id" bigint,
  "cost_state" varchar(20) NOT NULL DEFAULT 'pending',
  "created_by" bigint,
  CONSTRAINT "pk_inventory_transactions" PRIMARY KEY ("id","created_at"),
  CONSTRAINT "uq_inventory_transactions_public_id_created_at" UNIQUE ("public_id","created_at"),
  CONSTRAINT "fk_inventory_transactions_warehouse_id" FOREIGN KEY ("warehouse_id") REFERENCES erp."warehouses" (id) ON DELETE RESTRICT,
  CONSTRAINT "fk_inventory_transactions_location_id" FOREIGN KEY ("location_id") REFERENCES erp."warehouse_locations" (id) ON DELETE RESTRICT,
  CONSTRAINT "fk_inventory_transactions_product_variant_id" FOREIGN KEY ("product_variant_id") REFERENCES erp."product_variants" (id) ON DELETE RESTRICT,
  CONSTRAINT "uq_inventory_transactions_idempotency_key_created_at" UNIQUE ("idempotency_key","created_at"),
  CONSTRAINT "ck_inventory_transactions_qty_nonzero" CHECK (quantity <> 0)
) PARTITION BY RANGE ("created_at");
CREATE TABLE IF NOT EXISTS erp.inventory_transactions_default PARTITION OF erp.inventory_transactions DEFAULT;
CREATE INDEX IF NOT EXISTS ix_inventory_transactions_created_at_brin ON erp.inventory_transactions USING brin ("created_at") WITH (pages_per_range = 32);
CREATE TABLE IF NOT EXISTS erp.inventory_transactions_p202610 PARTITION OF erp.inventory_transactions FOR VALUES FROM ('2026-10-01 00:00:00+00') TO ('2026-11-01 00:00:00+00');
CREATE TABLE IF NOT EXISTS erp.inventory_transactions_p202611 PARTITION OF erp.inventory_transactions FOR VALUES FROM ('2026-11-01 00:00:00+00') TO ('2026-12-01 00:00:00+00');
CREATE INDEX IF NOT EXISTS ix_inventory_transactions_warehouse_id_product_variant_id_created_at ON erp."inventory_transactions" ("warehouse_id","product_variant_id","created_at");
CREATE INDEX IF NOT EXISTS ix_inventory_transactions_product_variant_id_created_at ON erp."inventory_transactions" ("product_variant_id","created_at");
CREATE INDEX IF NOT EXISTS ix_inventory_transactions_reference_type_reference_id ON erp."inventory_transactions" ("reference_type","reference_id");
CREATE INDEX IF NOT EXISTS ix_inventory_transactions_lot_id ON erp."inventory_transactions" ("lot_id");
CREATE INDEX IF NOT EXISTS ix_inventory_transactions_period_id ON erp."inventory_transactions" ("period_id");
CREATE INDEX IF NOT EXISTS ix_inventory_transactions_journal_entry_id ON erp."inventory_transactions" ("journal_entry_id");

