-- reservation rows; partial consumption
CREATE TABLE IF NOT EXISTS erp."stock_reservations" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "warehouse_id" bigint NOT NULL,
  "location_id" bigint NOT NULL,
  "product_variant_id" bigint NOT NULL,
  "quantity" numeric(18,4) NOT NULL,
  "consumed_qty" numeric(18,4) NOT NULL DEFAULT 0,
  "released_qty" numeric(18,4) NOT NULL DEFAULT 0,
  "consumed_transaction_id" bigint,
  "reference_type" varchar(40) NOT NULL,
  "reference_id" bigint NOT NULL,
  "reservation_no" varchar(50) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'active',
  "consumed_at" timestamptz,
  "released_at" timestamptz,
  "expires_at" timestamptz,
  "created_by" bigint,
  CONSTRAINT "pk_stock_reservations" PRIMARY KEY ("id"),
  CONSTRAINT "uq_stock_reservations_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_stock_reservations_reservation_no" UNIQUE ("reservation_no"),
  CONSTRAINT "ck_stock_reservations_consumption" CHECK (consumed_qty + released_qty <= quantity),
  CONSTRAINT "ck_stock_reservations_status" CHECK (status in ('active','partially_consumed','consumed','released','expired'))
);
CREATE INDEX IF NOT EXISTS ix_stock_reservations_reference_type_reference_id ON erp."stock_reservations" ("reference_type","reference_id");
CREATE INDEX IF NOT EXISTS ix_stock_reservations_warehouse_id_product_variant_id ON erp."stock_reservations" ("warehouse_id","product_variant_id");
CREATE INDEX IF NOT EXISTS ix_stock_reservations_status_expires_at ON erp."stock_reservations" ("status","expires_at");
CREATE TRIGGER trg_stock_reservations_updated_at BEFORE UPDATE ON erp."stock_reservations" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_stock_reservations_version BEFORE UPDATE ON erp."stock_reservations" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

