CREATE TABLE IF NOT EXISTS erp."accounting_dimensions" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "deleted_at" timestamptz,
  "organization_id" bigint NOT NULL,
  "code" varchar(50) NOT NULL,
  "name_fa" varchar(150) NOT NULL,
  "dimension_type" varchar(30) NOT NULL,
  "is_required" boolean NOT NULL DEFAULT false,
  "is_active" boolean NOT NULL DEFAULT true,
  CONSTRAINT "pk_accounting_dimensions" PRIMARY KEY ("id"),
  CONSTRAINT "uq_accounting_dimensions_public_id" UNIQUE ("public_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_accounting_dimensions_organization_id_code_active ON erp."accounting_dimensions" ("organization_id","code") WHERE deleted_at IS NULL;
CREATE TRIGGER trg_accounting_dimensions_updated_at BEFORE UPDATE ON erp."accounting_dimensions" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_accounting_dimensions_version BEFORE UPDATE ON erp."accounting_dimensions" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- partial unique (soft delete): dimension_id,code
-- dimension values (cost centers, projects)
CREATE TABLE IF NOT EXISTS erp."dimension_values" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "deleted_at" timestamptz,
  "dimension_id" bigint NOT NULL,
  "code" varchar(50) NOT NULL,
  "name_fa" varchar(200) NOT NULL,
  "parent_id" bigint,
  "reference_type" varchar(40),
  "reference_id" bigint,
  "is_active" boolean NOT NULL DEFAULT true,
  CONSTRAINT "pk_dimension_values" PRIMARY KEY ("id"),
  CONSTRAINT "uq_dimension_values_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_dimension_values_dimension_id" FOREIGN KEY ("dimension_id") REFERENCES erp."accounting_dimensions" (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_dimension_values_dimension_id ON erp."dimension_values" ("dimension_id");
CREATE INDEX IF NOT EXISTS ix_dimension_values_parent_id ON erp."dimension_values" ("parent_id");
CREATE UNIQUE INDEX IF NOT EXISTS uq_dimension_values_dimension_id_code_active ON erp."dimension_values" ("dimension_id","code") WHERE deleted_at IS NULL;
CREATE TRIGGER trg_dimension_values_updated_at BEFORE UPDATE ON erp."dimension_values" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_dimension_values_version BEFORE UPDATE ON erp."dimension_values" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- journal header; number at post, balance deferred
CREATE TABLE IF NOT EXISTS erp."journal_entries" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "updated_by" bigint,
  "version" integer NOT NULL DEFAULT 1,
  "organization_id" bigint NOT NULL,
  "fiscal_year_id" bigint NOT NULL,
  "period_id" bigint NOT NULL,
  "entry_no" varchar(60),
  "entry_date" date NOT NULL,
  "business_date" date NOT NULL,
  "entry_type" varchar(20) NOT NULL DEFAULT 'normal',
  "source_type" varchar(50),
  "source_id" bigint,
  "source_public_id" uuid,
  "source_event_uuid" uuid,
  "description" text NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'draft',
  "posted_at" timestamptz,
  "posted_by" bigint,
  "reversal_of_id" bigint,
  "voided_at" timestamptz,
  "void_reason" varchar(300),
  "total_debit_amount" bigint NOT NULL DEFAULT 0,
  "total_credit_amount" bigint NOT NULL DEFAULT 0,
  "approval_request_id" bigint,
  "posting_rule_set_id" bigint,
  CONSTRAINT "pk_journal_entries" PRIMARY KEY ("id"),
  CONSTRAINT "uq_journal_entries_public_id" UNIQUE ("public_id"),
  CONSTRAINT "uq_journal_entries_organization_id_entry_no" UNIQUE ("organization_id","entry_no"),
  CONSTRAINT "ck_journal_entries_balanced" CHECK (total_debit_amount = total_credit_amount),
  CONSTRAINT "ck_journal_entries_numbered" CHECK (status not in ('posted','approved') or entry_no is not null)
);
CREATE INDEX IF NOT EXISTS ix_journal_entries_period_id_entry_date ON erp."journal_entries" ("period_id","entry_date");
CREATE INDEX IF NOT EXISTS ix_journal_entries_source_type_source_id ON erp."journal_entries" ("source_type","source_id");
CREATE INDEX IF NOT EXISTS ix_journal_entries_status_entry_date ON erp."journal_entries" ("status","entry_date");
CREATE INDEX IF NOT EXISTS ix_journal_entries_source_event_uuid ON erp."journal_entries" ("source_event_uuid");
CREATE TRIGGER trg_journal_entries_updated_at BEFORE UPDATE ON erp."journal_entries" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_journal_entries_version BEFORE UPDATE ON erp."journal_entries" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

-- journal debit/credit lines
CREATE TABLE IF NOT EXISTS erp."journal_lines" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "journal_entry_id" bigint NOT NULL,
  "line_no" integer NOT NULL,
  "account_id" bigint NOT NULL,
  "debit_amount" bigint NOT NULL DEFAULT 0,
  "credit_amount" bigint NOT NULL DEFAULT 0,
  "description" text,
  "partner_type" varchar(30),
  "partner_id" bigint,
  "currency" char(3) NOT NULL DEFAULT 'IRR',
  "fx_rate" numeric(12,6) NOT NULL DEFAULT 1,
  "tax_rate_id" bigint,
  CONSTRAINT "pk_journal_lines" PRIMARY KEY ("id"),
  CONSTRAINT "uq_journal_lines_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_journal_lines_journal_entry_id" FOREIGN KEY ("journal_entry_id") REFERENCES erp."journal_entries" (id) ON DELETE CASCADE,
  CONSTRAINT "fk_journal_lines_account_id" FOREIGN KEY ("account_id") REFERENCES erp."chart_of_accounts" (id) ON DELETE RESTRICT,
  CONSTRAINT "uq_journal_lines_journal_entry_id_line_no" UNIQUE ("journal_entry_id","line_no"),
  CONSTRAINT "ck_journal_lines_one_side" CHECK ((debit_amount > 0 and credit_amount = 0) or (credit_amount > 0 and debit_amount = 0)),
  CONSTRAINT "ck_journal_lines_nonnegative" CHECK (debit_amount >= 0 and credit_amount >= 0)
);
CREATE INDEX IF NOT EXISTS ix_journal_lines_account_id ON erp."journal_lines" ("account_id");
CREATE INDEX IF NOT EXISTS ix_journal_lines_partner_type_partner_id ON erp."journal_lines" ("partner_type","partner_id");

-- dimension values on lines
CREATE TABLE IF NOT EXISTS erp."journal_line_dimensions" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "created_by" bigint,
  "journal_line_id" bigint NOT NULL,
  "dimension_id" bigint NOT NULL,
  "dimension_value_id" bigint NOT NULL,
  CONSTRAINT "pk_journal_line_dimensions" PRIMARY KEY ("id"),
  CONSTRAINT "uq_journal_line_dimensions_public_id" UNIQUE ("public_id"),
  CONSTRAINT "fk_journal_line_dimensions_journal_line_id" FOREIGN KEY ("journal_line_id") REFERENCES erp."journal_lines" (id) ON DELETE CASCADE,
  CONSTRAINT "fk_journal_line_dimensions_dimension_id" FOREIGN KEY ("dimension_id") REFERENCES erp."accounting_dimensions" (id) ON DELETE RESTRICT,
  CONSTRAINT "fk_journal_line_dimensions_dimension_value_id" FOREIGN KEY ("dimension_value_id") REFERENCES erp."dimension_values" (id) ON DELETE RESTRICT,
  CONSTRAINT "uq_journal_line_dimensions_journal_line_id_dimension_id" UNIQUE ("journal_line_id","dimension_id")
);
CREATE INDEX IF NOT EXISTS ix_journal_line_dimensions_dimension_value_id ON erp."journal_line_dimensions" ("dimension_value_id");

-- period balances (no dimension column)
CREATE TABLE IF NOT EXISTS erp."account_balances" (
  "id" bigint GENERATED ALWAYS AS IDENTITY,
  "public_id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
