CREATE INDEX IF NOT EXISTS ix_account_balances_account_id ON erp."account_balances" ("account_id");
CREATE INDEX IF NOT EXISTS ix_account_balances_fiscal_year_id ON erp."account_balances" ("fiscal_year_id");
CREATE TRIGGER trg_account_balances_updated_at BEFORE UPDATE ON erp."account_balances" FOR EACH ROW EXECUTE FUNCTION erp.set_updated_at();
CREATE TRIGGER trg_account_balances_version BEFORE UPDATE ON erp."account_balances" FOR EACH ROW EXECUTE FUNCTION erp.bump_version();

