-- ============================================================================
-- Hand-shaped integrity objects (journal balance, period derivation, partitioning, numbering)
-- ============================================================================
CREATE OR REPLACE FUNCTION erp.assert_journal_entry_balance() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_l int; v_d bigint; v_c bigint; v_h record;
BEGIN
  SELECT total_debit_amount, total_credit_amount, status INTO v_h FROM erp.journal_entries WHERE id = NEW.id;
  SELECT count(*), coalesce(sum(debit_amount),0), coalesce(sum(credit_amount),0)
    INTO v_l, v_d, v_c FROM erp.journal_lines WHERE journal_entry_id = NEW.id;
  IF v_h.status = 'posted' THEN
    IF v_l < 2 THEN RAISE EXCEPTION 'JOURNAL_UNBALANCED: entry % has % lines', NEW.id, v_l; END IF;
    IF v_d <> v_c THEN RAISE EXCEPTION 'JOURNAL_UNBALANCED: entry % debit % <> credit %', NEW.id, v_d, v_c; END IF;
    IF v_d = 0 THEN RAISE EXCEPTION 'JOURNAL_UNBALANCED: entry % has zero total', NEW.id; END IF;
    IF v_d <> v_h.total_debit_amount OR v_c <> v_h.total_credit_amount THEN
      RAISE EXCEPTION 'JOURNAL_UNBALANCED: entry % header totals mismatch', NEW.id; END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION erp.assert_journal_lines_balance() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_entry bigint; v_status varchar(20); v_l int; v_d bigint; v_c bigint;
BEGIN
  v_entry := coalesce(NEW.journal_entry_id, OLD.journal_entry_id);
  SELECT status INTO v_status FROM erp.journal_entries WHERE id = v_entry;
  IF v_status = 'posted' THEN
    SELECT count(*), coalesce(sum(debit_amount),0), coalesce(sum(credit_amount),0)
      INTO v_l, v_d, v_c FROM erp.journal_lines WHERE journal_entry_id = v_entry;
    IF v_l < 2 OR v_d <> v_c OR v_d = 0 THEN
      RAISE EXCEPTION 'JOURNAL_UNBALANCED: entry % (% lines, debit %, credit %)', v_entry, v_l, v_d, v_c;
    END IF;
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER trg_journal_entries_assert_balanced
  AFTER INSERT OR UPDATE ON erp.journal_entries
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION erp.assert_journal_entry_balance();
CREATE CONSTRAINT TRIGGER trg_journal_lines_assert_balanced
  AFTER INSERT OR UPDATE OR DELETE ON erp.journal_lines
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION erp.assert_journal_lines_balance();

CREATE OR REPLACE FUNCTION erp.derive_journal_period() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_period record;
BEGIN
  SELECT p.id, p.fiscal_year_id, p.status INTO v_period
    FROM erp.accounting_periods p
   WHERE NEW.entry_date BETWEEN p.start_date AND p.end_date
   ORDER BY p.period_no LIMIT 1;
  IF v_period.id IS NULL THEN RAISE EXCEPTION 'PERIOD_NOT_FOUND: no accounting period for %', NEW.entry_date; END IF;
  IF v_period.status IN ('closed','locked') THEN RAISE EXCEPTION 'PERIOD_CLOSED: % is closed', NEW.entry_date; END IF;
  NEW.period_id := v_period.id;
  NEW.fiscal_year_id := v_period.fiscal_year_id;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_journal_entries_derive_period BEFORE INSERT OR UPDATE OF entry_date ON erp.journal_entries
  FOR EACH ROW EXECUTE FUNCTION erp.derive_journal_period();

-- fiscal-year / period non-overlap (btree_gist EXCLUDE)
ALTER TABLE erp.fiscal_years ADD CONSTRAINT ex_fiscal_years_no_overlap
  EXCLUDE USING gist (organization_id WITH =, daterange(start_date, end_date, '[]') WITH &&) DEFERRABLE;
ALTER TABLE erp.accounting_periods ADD CONSTRAINT ex_accounting_periods_no_overlap
  EXCLUDE USING gist (fiscal_year_id WITH =, daterange(start_date, end_date, '[]') WITH &&) DEFERRABLE;
-- partition maintenance (SECURITY DEFINER, identifier-safe)
CREATE OR REPLACE FUNCTION erp.ensure_month_partition(p_parent regclass, p_month date)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = erp, public, pg_temp AS $$
DECLARE v_nsp text; v_rel text; v_part text;
        v_start timestamptz := date_trunc('month', p_month)::timestamptz;
        v_end timestamptz := (date_trunc('month', p_month) + interval '1 month')::timestamptz;
BEGIN
  SELECT n.nspname, c.relname INTO v_nsp, v_rel FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.oid = p_parent;
  IF v_nsp IS DISTINCT FROM 'erp' THEN RAISE EXCEPTION 'partition parent must be in erp: %', p_parent; END IF;
  IF v_rel !~ '^[a-z][a-z0-9_]*$' THEN RAISE EXCEPTION 'invalid relation name: %', v_rel; END IF;
  v_part := v_rel || '_p' || to_char(v_start, 'YYYYMM');
  IF to_regclass(format('%I.%I', v_nsp, v_part)) IS NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext(v_nsp || '.' || v_rel));
    EXECUTE format('CREATE TABLE %I.%I PARTITION OF %I.%I FOR VALUES FROM (%L) TO (%L)', v_nsp, v_part, v_nsp, v_rel, v_start, v_end);
  END IF;
  RETURN v_part;
END $$;

CREATE OR REPLACE FUNCTION erp.maintain_partitions(p_ahead_months integer DEFAULT 2)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = erp, public, pg_temp AS $$
DECLARE r record; m date; created int := 0;
BEGIN
  FOR r IN SELECT parent_table FROM erp.partitioned_tables_registry WHERE is_enabled LOOP
    FOR m IN SELECT generate_series(date_trunc('month', now())::date,
               (date_trunc('month', now()) + (p_ahead_months || ' months')::interval)::date, interval '1 month')::date LOOP
      PERFORM erp.ensure_month_partition(r.parent_table::regclass, m);
      created := created + 1;
    END LOOP;
  END LOOP;
  INSERT INTO erp.partition_maintenance_log(parent_table, action, partition_name, success, detail)
  VALUES ('*','create','*',true, format('ensured next %s months; %s checks', p_ahead_months, created));
  RETURN created;
END $$;

CREATE OR REPLACE FUNCTION erp.drain_default_partition(p_parent regclass, p_month date)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = erp, public, pg_temp AS $$
DECLARE v_nsp text; v_rel text; v_part text; v_rows bigint;
BEGIN
  SELECT n.nspname, c.relname INTO v_nsp, v_rel FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.oid = p_parent;
  v_part := erp.ensure_month_partition(p_parent, p_month);
  EXECUTE format('WITH moved AS (DELETE FROM %I.%I WHERE created_at >= %L AND created_at < %L RETURNING *) INSERT INTO %I.%I SELECT * FROM moved',
    v_nsp, v_rel || '_default', date_trunc('month', p_month)::timestamptz,
    (date_trunc('month', p_month) + interval '1 month')::timestamptz, v_nsp, v_part);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END $$;

REVOKE ALL ON FUNCTION erp.ensure_month_partition(regclass, date) FROM PUBLIC;
REVOKE ALL ON FUNCTION erp.maintain_partitions(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION erp.drain_default_partition(regclass, date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION erp.ensure_month_partition(regclass, date) TO saman_worker;
GRANT EXECUTE ON FUNCTION erp.maintain_partitions(integer) TO saman_worker;
GRANT EXECUTE ON FUNCTION erp.drain_default_partition(regclass, date) TO saman_worker;
-- document numbering: gap-free per (org, type, fiscal year), ADR-0014
CREATE OR REPLACE FUNCTION erp.allocate_document_no(p_org_id bigint, p_document_type varchar, p_fiscal_year_id bigint)
RETURNS varchar LANGUAGE plpgsql AS $$
DECLARE v_next bigint; v_prefix varchar(20); v_padding smallint;
BEGIN
  UPDATE erp.numbering_sequences
     SET next_value = next_value + 1, last_allocated_at = now()
   WHERE organization_id = p_org_id
     AND document_type = p_document_type
     AND fiscal_year_id IS NOT DISTINCT FROM p_fiscal_year_id
  RETURNING next_value - 1, prefix, padding INTO v_next, v_prefix, v_padding;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NUMBERING_SEQUENCE_MISSING: % / % / %', p_org_id, p_document_type, p_fiscal_year_id;
  END IF;
  RETURN v_prefix || '-' || to_char(now(), 'YYYY') || '-' || lpad(v_next::text, v_padding, '0');
END $$;
-- audit hash chain (SECURITY DEFINER; only this function writes the chain columns + head)
CREATE OR REPLACE FUNCTION erp.chain_audit(p_batch integer DEFAULT 500)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = erp, public, pg_temp AS $$
DECLARE r record; v_head record; v_prev char(64); v_seq bigint; v_hash char(64); v_next_id bigint; n int := 0;
BEGIN
  SELECT * INTO v_head FROM erp.audit_chain_heads WHERE organization_id = 1 FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO erp.audit_chain_heads(organization_id, last_row_hash) VALUES (1, encode(digest('genesis','sha256'),'hex'))
    RETURNING * INTO v_head;
  END IF;
  v_prev := v_head.last_row_hash; v_seq := coalesce(v_head.last_audit_id, 0);
  FOR r IN SELECT id, created_at FROM erp.audit_logs
            WHERE organization_id = 1 AND entry_hash IS NULL
            ORDER BY created_at, id LIMIT p_batch LOOP
    v_seq := v_seq + 1;
    v_hash := encode(digest(coalesce(v_prev,'') || '|' || r.id::text || '|' || r.created_at::text, 'sha256'),'hex');
    UPDATE erp.audit_logs SET prev_hash = v_prev, entry_hash = v_hash, hash_seq = v_seq WHERE id = r.id AND created_at = r.created_at;
    v_prev := v_hash; v_next_id := r.id; n := n + 1;
  END LOOP;
  IF n > 0 THEN
    UPDATE erp.audit_chain_heads SET last_audit_id = v_next_id, last_created_at = now(), last_row_hash = v_prev, updated_at = now() WHERE organization_id = 1;
  END IF;
  RETURN n;
END $$;
REVOKE ALL ON FUNCTION erp.chain_audit(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION erp.chain_audit(integer) TO saman_worker;
-- ============================================================================
-- Grants manifest (R1-S H-12): app = no DELETE; readonly = views only
-- ============================================================================
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_app') THEN CREATE ROLE saman_app NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_migrator') THEN CREATE ROLE saman_migrator NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_worker') THEN CREATE ROLE saman_worker NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'saman_readonly') THEN CREATE ROLE saman_readonly NOLOGIN; END IF;
END $$;
GRANT USAGE ON SCHEMA erp TO saman_app, saman_worker, saman_readonly, saman_migrator;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA erp TO saman_app;
REVOKE DELETE, TRUNCATE ON ALL TABLES IN SCHEMA erp FROM saman_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA erp TO saman_worker;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA erp TO saman_app, saman_worker;
ALTER DEFAULT PRIVILEGES IN SCHEMA erp GRANT SELECT, INSERT, UPDATE ON TABLES TO saman_app;
GRANT SELECT ON ALL TABLES IN SCHEMA erp TO saman_readonly;
REVOKE SELECT ON erp.users, erp.auth_sessions, erp.password_history, erp.user_devices, erp.otp_challenges, erp.security_events, erp.system_settings, erp.api_clients, erp.channel_credentials, erp.channel_webhook_secrets, erp.webhook_subscriptions, erp.audit_logs FROM saman_readonly;
REVOKE UPDATE, DELETE ON erp.audit_logs, erp.inventory_transactions, erp.channel_api_calls, erp.api_request_logs FROM saman_app;
GRANT SELECT, INSERT ON erp.audit_logs TO saman_app;


SET search_path TO public;
